<?php
namespace App\Services; use PDO;
final class WalletService { public static function move(PDO $db,int $uid,float $delta,string $type,string $ref,string $idem):array{$dup=$db->prepare('SELECT id,balance_after FROM transactions WHERE idempotency_key=? LIMIT 1');$dup->execute([$idem]);if($row=$dup->fetch())return ['duplicate'=>true,'balance'=>(float)$row['balance_after']];$q=$db->prepare('SELECT balance FROM users WHERE id=? FOR UPDATE');$q->execute([$uid]);$before=$q->fetchColumn();if($before===false)throw new \RuntimeException('User tidak ditemukan');$after=(float)$before+$delta;if($after<0)throw new \RuntimeException('Saldo tidak cukup');$db->prepare('UPDATE users SET balance=? WHERE id=?')->execute([$after,$uid]);$db->prepare('INSERT INTO transactions(user_id,type,reference,idempotency_key,amount,balance_before,balance_after,created_at) VALUES(?,?,?,?,?,?,?,NOW())')->execute([$uid,$type,$ref,$idem,$delta,$before,$after]);return ['duplicate'=>false,'balance'=>$after];}}
